<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
use DigiForge\Database\Tables;
use DigiForge\Listings\DraftQaReviewRepository;
final class DraftQaWorkflowAcceptanceTest extends WP_UnitTestCase {
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();ShopAccessFixture::reset();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['digital','personalized_pod','standard_pod','jewelry'],DigiForge\Core\Capabilities::ALL);}
 private function fixture():array {
  $factory=new DigiForge\ProductFactory\Repository();$opp=$factory->create('opportunity',['title'=>'Local draft review fixture']);self::assertNotWPError($opp);$family=$factory->create('product_family',['opportunity_id'=>$opp['id'],'name'=>'Draft fixture']);self::assertNotWPError($family);$product=$factory->create('product',['product_family_id'=>$family['id'],'name'=>'Draft fixture']);self::assertNotWPError($product);$version=$factory->create('product_version',['product_id'=>$product['id'],'version_label'=>'v1']);self::assertNotWPError($version);foreach(['REVIEW','APPROVED']as $state)self::assertNotWPError($factory->transition('product_version',(int)$version['id'],$state));
  $production=new DigiForge\Production\Repository();$spec=$production->createSpec(['product_version_id'=>$version['id'],'asset_key'=>'review-fixture','asset_type'=>'image','format'=>'png']);self::assertNotWPError($spec);$revision=$production->addRevision(['asset_spec_id'=>$spec['id'],'revision_label'=>'v1','storage_reference'=>'local://synthetic-review-fixture/preview.png','checksum_sha256'=>hash('sha256','synthetic media'),'mime_type'=>'image/png','byte_size'=>16,'width_px'=>2,'height_px'=>2]);self::assertNotWPError($revision);self::assertNotWPError($production->addQa(['target_type'=>'revision','target_id'=>$revision['id'],'check_type'=>'synthetic_fixture','status'=>'PASS','details'=>['fixture_only'=>true]]));foreach(['QA_PASSED','APPROVED']as $state)self::assertNotWPError($production->transition('revision',(int)$revision['id'],$state));
  $listings=new DigiForge\Listings\Repository();$listing=$listings->createListing(['product_version_id'=>$version['id'],'environment'=>'sandbox','channel'=>'etsy','shop_reference'=>'digital','title'=>'Local reviewed draft','description'=>'Synthetic local reviewed scope only.','price_amount'=>12,'currency'=>'USD']);self::assertNotWPError($listing);self::assertNotWPError($listings->setSeo(['listing_id'=>$listing['id'],'tags'=>['fixture','local']]));self::assertNotWPError($listings->bindMedia(['listing_id'=>$listing['id'],'asset_revision_id'=>$revision['id']]));foreach(['VALIDATED','REVIEW_REQUIRED']as $state)self::assertNotWPError($listings->transition('listing',(int)$listing['id'],$state));$review=$listings->createReadinessReview((int)$listing['id']);self::assertNotWPError($review);self::assertNotWPError($listings->decideReadinessReview((int)$review['id'],'APPROVED'));$package=$listings->createDraftPackage(['listing_id'=>$listing['id'],'package_version'=>'review-v1']);self::assertNotWPError($package);
  $intent=$listings->createIntent(['listing_id'=>$listing['id'],'draft_package_id'=>$package['id'],'environment'=>'sandbox','intent_type'=>'PREPARE_DRAFT']);self::assertNotWPError($intent);global $wpdb;$now=current_time('mysql',true);self::assertSame(1,$wpdb->update(Tables::etsy_intents(),['state'=>'APPROVED_INTENT'],['id'=>$intent['id']]));$hash=hash('sha256','fixture');$base=['shop_reference'=>'1234','intent_id'=>$intent['id'],'draft_package_id'=>$package['id'],'state'=>'CONFIRMED_SUCCESS','external_reference'=>'5678','request_fingerprint'=>$hash,'authorization_hash'=>$hash,'evidence_hash'=>$hash,'created_at'=>$now,'updated_at'=>$now];self::assertSame(1,$wpdb->insert($wpdb->prefix.'digiforge_etsy_operations',$base+['operation_type'=>'CREATE_DRAFT','idempotency_key'=>'draft-'.wp_generate_uuid4()]));$create=(int)$wpdb->insert_id;self::assertSame(1,$wpdb->insert($wpdb->prefix.'digiforge_etsy_operations',$base+['operation_type'=>'UPLOAD_FILE','resource_reference'=>'5678','external_asset_reference'=>'9012','idempotency_key'=>'file-'.wp_generate_uuid4()]));return ['listing'=>(int)$listing['id'],'intent'=>(int)$intent['id'],'package'=>(int)$package['id'],'create'=>$create,'upload'=>(int)$wpdb->insert_id];
 }
 private function checks():array{return array_fill_keys(['title','description','seo','media','pricing','policy','personalization'],'PASS');}
 public function testCurrentHumanReviewRequiresRecordedDraftAndFileThenDeniesPublishAuthority():void {
  $f=$this->fixture();$repo=new DraftQaReviewRepository();self::assertWPError($repo->verify($f['intent'],$f['package'],'1234'));$context=$repo->inspect($f['create']);self::assertNotWPError($context);$review=$repo->record($f['intent'],$f['package'],$f['create'],$this->checks(),'CONFIRM_DRAFT_QA_REVIEW',$context['objective_evidence_hash']);self::assertNotWPError($review);$verified=$repo->verify($f['intent'],$f['package'],'1234');self::assertNotWPError($verified);self::assertFalse($verified['publish_authorized']);self::assertFalse($verified['commercial_semantic_truth_certified']);self::assertSame($f['upload'],$verified['context']['attachment_operation_id']);self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 public function testStaleFailedMissingAttachmentAndUnauthorizedReviewFailClosed():void {
  $f=$this->fixture();$repo=new DraftQaReviewRepository();$context=$repo->inspect($f['create']);self::assertNotWPError($context);self::assertWPError($repo->record($f['intent'],$f['package'],$f['create'],$this->checks(),'WRONG',$context['objective_evidence_hash']));$checks=$this->checks();$checks['media']='FAIL';self::assertNotWPError($repo->record($f['intent'],$f['package'],$f['create'],$checks,'CONFIRM_DRAFT_QA_REVIEW',$context['objective_evidence_hash']));self::assertWPError($repo->verify($f['intent'],$f['package'],'1234'));
  global $wpdb;self::assertSame(1,$wpdb->update($wpdb->prefix.'digiforge_etsy_operations',['resource_reference'=>'different'],['id'=>$f['upload']]));self::assertWPError($repo->inspect($f['create']));wp_set_current_user(0);self::assertWPError($repo->record($f['intent'],$f['package'],$f['create'],$this->checks(),'CONFIRM_DRAFT_QA_REVIEW',$context['objective_evidence_hash']));
 }
 public function testPublishControllerRejectsMissingQaBeforeConnectorOrAuthorizationUnderSyntheticReadInterlock():void {
  $f=$this->fixture();global $wpdb;$reads=static function($sql)use($wpdb){if(str_contains($sql,'SELECT setting_value, setting_type FROM '.Tables::settings())){if(str_contains($sql,"'stop_all'"))return "SELECT 'false' AS setting_value, 'boolean' AS setting_type";return "SELECT 'true' AS setting_value, 'boolean' AS setting_type";}return $sql;};$calls=0;$http=static function()use(&$calls){$calls++;return new WP_Error('offline_fixture','Forbidden HTTP.');};$request=new WP_REST_Request('POST','/digiforge/v1/etsy/publish-listing');$request->set_header('Content-Type','application/json');$request->set_header('Idempotency-Key','qa-missing');$request->set_body(wp_json_encode(['integration_id'=>123,'shop_id'=>1234,'intent_id'=>$f['intent'],'draft_package_id'=>$f['package']]));add_filter('query',$reads);add_filter('pre_http_request',$http);
  try{$result=(new DigiForge\REST\EtsyPublishExecutionController())->execute($request);}finally{remove_filter('query',$reads);remove_filter('pre_http_request',$http);}
  self::assertWPError($result);self::assertSame('digiforge_draft_qa_review_missing',$result->get_error_code());self::assertSame(0,$calls);self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 public function testActualRestReviewRequiresNonceAndSignedExplicitConfirmationBeforeRecording():void {
  $f=$this->fixture();$repo=new DraftQaReviewRepository();$context=$repo->inspect($f['create']);self::assertNotWPError($context);$body=['intent_id'=>$f['intent'],'draft_package_id'=>$f['package'],'create_operation_id'=>$f['create'],'checks'=>$this->checks(),'objective_evidence_hash'=>$context['objective_evidence_hash'],'confirmation'=>'CONFIRM_DRAFT_QA_REVIEW'];
  $params=DigiForge\Portal\ReviewConfirmation::parameters(DraftQaReviewRepository::ACTION,$body);$receipt=DigiForge\Portal\ReviewConfirmation::inspect(DraftQaReviewRepository::ACTION,$f['create'],'digital',$params);self::assertNotWPError($receipt);$body+=['df_confirmation_shop'=>'digital','df_confirmation_tokens'=>['REVIEW'=>$receipt['token']],'df_confirmation_nonce'=>$receipt['confirmation_nonce'],'df_confirmation_issued_at'=>$receipt['issued_at']];
  $request=new WP_REST_Request('POST','/digiforge/v1/listings/draft-qa');$request->set_header('Content-Type','application/json');$request->set_header('Idempotency-Key','qa-route-'.wp_generate_uuid4());$request->set_body(wp_json_encode($body));$controller=new DigiForge\REST\ListingController();self::assertWPError($controller->recordDraftQa($request));$request->set_header('X-WP-Nonce',wp_create_nonce('wp_rest'));self::assertWPError($controller->recordDraftQa($request));self::assertWPError($repo->verify($f['intent'],$f['package'],'1234'));
  $body['df_confirm_review']='1';$request->set_body(wp_json_encode($body));$record=$controller->recordDraftQa($request);self::assertInstanceOf(WP_REST_Response::class,$record);self::assertSame(201,$record->get_status());self::assertNotWPError($repo->verify($f['intent'],$f['package'],'1234'));self::assertFalse($record->get_data()['publish_authorized']);self::assertWPError($controller->recordDraftQa($request));self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }

}
